import React,{Component} from "react";

class Student extends Component{
    render(){
        return(
            <div>
            <h2>name:{this.props.name}</h2>
            <h2>age:{this.props.age}</h2>
            </div>
        )
    }
}

class App extends Component{
    render(){
        return(
            <div>
                <h1>student details</h1>
                <Student name = "tez" age = {17}/>
            </div>
        )
    }
}

export default App;
